#include <vector>

class Solution {
public:
    std::vector<int> elementInNums(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size();
        int period = 2 * n;
        std::vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int time = q[0], idx = q[1];
            int m = time % period;
            if (m < n) {
                int remLen = n - m;
                if (idx < remLen) ans.push_back(nums[m + idx]);
                else ans.push_back(-1);
            } else {
                int remLen = m - n;
                if (idx < remLen) ans.push_back(nums[idx]);
                else ans.push_back(-1);
            }
        }
        return ans;
    }
};

class Solution {
    public int[] elementInNums(int[] nums, int[][] queries) {
        int n = nums.length;
        int period = 2 * n;
        int[] ans = new int[queries.length];

        for (int i = 0; i < queries.length; i++) {
            int time = queries[i][0];
            int idx = queries[i][1];
            int m = time % period;

            if (m < n) {
                int remLen = n - m;
                if (idx < remLen) ans[i] = nums[m + idx];
                else ans[i] = -1;
            } else {
                int remLen = m - n;
                if (idx < remLen) ans[i] = nums[idx];
                else ans[i] = -1;
            }
        }
        return ans;
    }
}

