var elementInNums = function(nums, queries) {
    const n = nums.length;
    const period = 2 * n;
    const ans = [];

    for (const [time, idx] of queries) {
        const m = time % period;
        if (m < n) {
            const remLen = n - m;
            if (idx < remLen) ans.push(nums[m + idx]);
            else ans.push(-1);
        } else {
            const remLen = m - n;
            if (idx < remLen) ans.push(nums[idx]);
            else ans.push(-1);
        }
    }
    return ans;
};
